using System;using System.Buffers.Binary;using OpenCvSharp;using SarmatVisionHold.KestrelClient.Models;
namespace SarmatVisionHold.KestrelClient.Networking {
 public sealed class KdvfFrameDecoder { public const int HeaderSize=46,ProtocolVersion=1,JpegEncoding=1;readonly int maxBytes;public KdvfFrameDecoder(int maxFrameBytes=8*1024*1024){maxBytes=maxFrameBytes;}
  public bool TryDecode(byte[] data,out KestrelFrame frame,out string error){frame=null;error=null;if(data==null||data.Length<HeaderSize)return Fail("Frame is shorter than KDVF header",out error);if(data[0]!=75||data[1]!=68||data[2]!=86||data[3]!=70)return Fail("Invalid KDVF magic",out error);var s=new ReadOnlySpan<byte>(data);var version=BinaryPrimitives.ReadUInt16LittleEndian(s.Slice(4,2));var header=BinaryPrimitives.ReadUInt16LittleEndian(s.Slice(6,2));if(version!=ProtocolVersion)return Fail("Unsupported protocolVersion: "+version,out error);if(header!=HeaderSize)return Fail("Invalid headerSize: "+header,out error);var payload=BinaryPrimitives.ReadUInt32LittleEndian(s.Slice(42,4));if(payload>maxBytes)return Fail("Frame payload exceeds configured maximum",out error);if(payload!=data.Length-HeaderSize)return Fail("payloadLength does not match message size",out error);var encoding=data[40];if(encoding!=JpegEncoding)return Fail("Unknown frame encoding: "+encoding,out error);var uuid=Hex(s.Slice(8,16));if(!Guid.TryParseExact(uuid,"N",out var id))return Fail("Invalid session UUID",out error);var jpeg=new byte[payload];Buffer.BlockCopy(data,HeaderSize,jpeg,0,(int)payload);Mat image;try{image=Cv2.ImDecode(jpeg,ImreadModes.Color);}catch(Exception e){return Fail("JPEG decode failed: "+e.Message,out error);}if(image==null||image.Empty()){image?.Dispose();return Fail("JPEG decoded to an empty image",out error);}var width=BinaryPrimitives.ReadUInt16LittleEndian(s.Slice(36,2));var height=BinaryPrimitives.ReadUInt16LittleEndian(s.Slice(38,2));if(image.Width!=width||image.Height!=height){image.Dispose();return Fail($"Decoded dimensions {image.Width}x{image.Height} differ from header {width}x{height}",out error);}frame=new KestrelFrame{ProtocolVersion=version,SessionId=id,TimestampUs=BinaryPrimitives.ReadUInt64LittleEndian(s.Slice(24,8)),FrameNumber=BinaryPrimitives.ReadUInt32LittleEndian(s.Slice(32,4)),Width=width,Height=height,Encoding=encoding,Jpeg=jpeg,Image=image,ReceivedUtc=DateTime.UtcNow};return true;}
  static string Hex(ReadOnlySpan<byte> bytes){var c=new char[bytes.Length*2];const string h="0123456789abcdef";for(int i=0;i<bytes.Length;i++){c[i*2]=h[bytes[i]>>4];c[i*2+1]=h[bytes[i]&15];}return new string(c);}static bool Fail(string value,out string error){error=value;return false;}
 }
}
